create table arsenich_destination_intro (
  destination_key text primary key check (destination_key in (
    'main', 'daily', 'sections', 'training', 'tasks', 'shop', 'bonus-games',
    'amateur', 'chat', 'profile-main'
  )),
  enabled boolean not null default true,
  revision integer not null default 1 check (revision > 0),
  windows jsonb not null check (
    jsonb_typeof(windows) = 'array' and jsonb_array_length(windows) between 1 and 2
  ),
  updated_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table arsenich_destination_intro_view (
  user_id uuid not null references users(id) on delete cascade,
  destination_key text not null references arsenich_destination_intro(destination_key) on delete cascade,
  viewed_revision integer not null check (viewed_revision > 0),
  viewed_at timestamptz not null default now(),
  primary key (user_id, destination_key)
);

insert into arsenich_destination_intro (destination_key, windows) values
('main', '[{"title":"Видишь куб? Через него можно быстро попасть в игру","body":"Куб показывает, что сейчас происходит в разных режимах.\n\n- Листай экраны куба стрелками или свайпом.\n- На табло появляются ежедневная игра, тренировки, турниры и активные дуэли.\n- Кнопка под табло откроет выбранную игру. Во время перерыва или восстановления куб покажет, сколько осталось ждать.","ctaLabel":"Понятно"}]'),
('daily', '[{"title":"Смотри, здесь у тебя матч на каждый день","body":"Матч разбит на периоды, поэтому можно сыграть часть сейчас и вернуться позже.\n\n- В верхней карточке видно текущий период, время и счёт.\n- Результаты прошлых игр останутся в истории и календаре.\n- Забитые шайбы идут в твою общую статистику игрока.","ctaLabel":"Понятно"}]'),
('sections', '[{"title":"Здесь ты выбираешь, чем будешь заниматься","body":"Это главный список режимов игры.\n\n- В быстром доступе лежат ежедневная игра, тренировки, задания и магазин.\n- Ниже открываются бонусные игры и матчи с другими игроками.\n- Нажми на карточку раздела, чтобы перейти в него.","ctaLabel":"Ясно"}]'),
('training', '[{"title":"Начни с первого упражнения. Так поставишь бросок","body":"Курс проведёт тебя от простых бросков до игрового темпа. Каждое следующее упражнение добавляет новую сложность.\n\n- Сначала будут пустые неподвижные ворота.\n- Потом появятся новые позиции, движение и вратарь.\n- Открой первое доступное упражнение и проходи курс по порядку.","ctaLabel":"Попробую"}]'),
('tasks', '[{"title":"После игры заглядывай сюда за наградами","body":"Здесь игра даёт дополнительные цели. Выполняй условия во время матчей и следи, как заполняется прогресс.\n\n- Во вкладке «Задания» цели открываются по уровням.\n- Во вкладке «Челленджи» лежат отдельные испытания.\n- Выполнил условие - вернись сюда и забери награду с карточки.","ctaLabel":"Запомнил"}]'),
('shop', '[{"title":"Если что-то понадобится для игры, ищи здесь","body":"В магазине можно купить экипировку и расходники за игровую валюту. Перед покупкой проверь цену и описание предмета.\n\n- В «Товарах» лежат клюшки, коньки и расходники.\n- В «Банке» можно пополнить запас монет.\n- В «Истории» видны прошлые операции. Купленную экипировку выбери в профиле.","ctaLabel":"Хорошо"}]'),
('bonus-games', '[{"title":"Хочешь проверить свои навыки? Тебе сюда","body":"Бонусные игры прокачивают отдельные способности игрока и проходят по своим правилам. Перед стартом открой карточку и прочитай условие.\n\n- Сверху можно переключаться между скоростью и точностью.\n- На карточке указаны цель игры и доступные попытки.\n- Выбери игру, посмотри превью и только потом выходи на лёд.","ctaLabel":"Разобрался"}]'),
('amateur', '[{"title":"Здесь играют против других игроков","body":"В разделе любителей проходят дуэли и турниры. Смотреть матчи, рейтинги и результаты могут все игроки, а участвовать - только любители и профессионалы.\n\n- В «Дуэлях» выбирай формат и соперника. Не забывай проверять доступный лимит матчей.\n- У каждого формата есть свой рейтинг, а ещё общий. Рейтинги обновляются каждый месяц.\n- В «Турнирах» проходят регулярный этап и плей-офф. Здесь же находятся таблица, расписание и турнирная сетка.","ctaLabel":"Понятно"}]'),
('chat', '[{"title":"Здесь можешь найти других игроков и написать им","body":"На этой странице собраны личные диалоги, общий канал и чаты, а также рассылки от приложения.\n\n- В общем канале читай свежие новости и оставляй комментарии.\n- Разговоры в общем чате приветствуются:)\n- Но ты можешь писать любому участнику игры в личку и даже вызывать его на дуэль.","ctaLabel":"Ясно"}]'),
('profile-main', '[{"title":"Смотри, вот чего ты уже добился","body":"Профиль показывает, как развивается твой игрок и с чем он выходит на лёд.\n\n- Сверху видны уровень, опыт и игровая валюта.\n- Показатели кликабельные, ты всегда можешь посмотреть своё место в рейтинге.\n- В настройках можно изменить имя, аватар и хват игрока, настроить уведомления, отправить отзыв или написать в личку админам.","ctaLabel":"Понятно"}]');
